#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CONTEXTS 1000
#define RADIX 255

typedef struct {
    FILE *out;
    uint64_t low;
    uint64_t high;
    uint64_t pending;
    int cc[MAX_CONTEXTS * 2];
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->low = 0;
    e->high = 0xFFFFFFFFFFFFFFFFULL;
    e->pending = 0;
    memset(e->cc, 0, sizeof(e->cc));
}

void encode_bit(Encoder *e, int bit, int ctx) {
    int *counts = e->cc + ctx * 2;

    uint64_t range = e->high - e->low + 1;
    int total = counts[0] + counts[1] + 2;
    uint64_t split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    // Output bytes when needed
    while ((e->high - e->low + 1) < (1ULL << 24)) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        fputc(byte + 1, e->out);  // gc() returns byte+1, so output byte+1
        e->low = (e->low << 8) & 0xFFFFFFFFFFFFFFFFULL;
        e->high = ((e->high << 8) | 0xFF) & 0xFFFFFFFFFFFFFFFFULL;
    }
}

void encode_integer(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (!(encoded & (1 << (temp - 1))) || temp == 31) {
        encode_bit(e, 1, ctx_base + temp + 1);
        temp++;
        if (temp > 31) break;
    }

    encode_bit(e, 0, ctx_base + temp + 1);
    temp--;

    for (int i = temp - 1; i >= 0; i--) {
        int bit = (encoded >> i) & 1;
        encode_bit(e, bit, ctx_base);
    }
}

void finish_encoder(Encoder *e) {
    while ((e->high - e->low + 1) < (1ULL << 24)) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        fputc(byte + 1, e->out);
        e->low = (e->low << 8) & 0xFFFFFFFFFFFFFFFFULL;
        e->high = ((e->high << 8) | 0xFF) & 0xFFFFFFFFFFFFFFFFULL;
    }
}

struct Match {
    int offset;
    int length;
};

struct Match find_match(unsigned char *data, int pos, int max_offset) {
    struct Match best = {-1, 0};

    if (pos < 1) return best;

    for (int off = 1; off <= max_offset && off <= pos; off++) {
        int len = 0;
        while (len < 3 && pos + len < 4868 &&
               data[pos - off + len] == data[pos + len]) {
            len++;
        }
        if (len > best.length) {
            best.offset = off - 1;  // Store as 0-based
            best.length = len - 1;  // Store as 0-based
        }
    }

    return best;
}

int main() {
    unsigned char data[10000];
    FILE *f = fopen("/app/data.txt", "rb");
    int len = fread(data, 1, sizeof(data), f);
    fclose(f);

    FILE *out = fopen("/app/data.comp", "wb");
    Encoder enc;
    init_encoder(&enc, out);

    int cmd_count = 0;
    int pos = 0;

    // First pass: count commands
    while (pos < len) {
        struct Match m = find_match(data, pos, 31);
        if (m.offset >= 0) {
            cmd_count++;
            pos += m.length + 1;
        } else {
            cmd_count++;
            pos++;
        }
    }

    printf("Data size: %d bytes\n", len);
    printf("Command count: %d\n", cmd_count);

    // Encode count
    encode_integer(&enc, cmd_count, 9, 0);

    // Second pass: encode commands
    pos = 0;
    while (pos < len) {
        struct Match m = find_match(data, pos, 31);
        if (m.offset >= 0) {
            encode_bit(&enc, 1, 1);
            encode_integer(&enc, m.offset, 5, 2);
            encode_integer(&enc, m.length, 2, 3);
            pos += m.length + 1;
        } else {
            encode_bit(&enc, 0, 1);
            int byte_val = data[pos];
            int sign = byte_val > 127 ? 1 : 0;
            encode_bit(&enc, sign, 8);
            int value = sign ? byte_val - 256 : byte_val;
            if (value < 0) value = -value;
            encode_integer(&enc, value, 4, 9);
            pos++;
        }
    }

    finish_encoder(&enc);
    fclose(out);

    // Check file size
    f = fopen("/app/data.comp", "rb");
    fseek(f, 0, SEEK_END);
    long comp_size = ftell(f);
    fclose(f);

    printf("Compressed size: %ld bytes\n", comp_size);
    printf("Ratio: %.1f%%\n", 100.0 * comp_size / len);

    return 0;
}

