#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    FILE *out;
    unsigned char *buf;
    int buf_pos;
    uint64_t low;
    uint64_t high;
    uint32_t cc[1000000];
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->buf = malloc(100000);
    e->buf_pos = 0;
    e->low = 0;
    e->high = 0xFFFFFFFFFFFFFFFFULL;
    memset(e->cc, 0, sizeof(e->cc));
}

void encode_bit(Encoder *e, int bit, int ctx) {
    uint32_t *counts = e->cc + ctx * 2;
    uint64_t range = e->high - e->low + 1;

    uint32_t total = counts[0] + counts[1] + 2;
    uint64_t split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    // Output bytes when high - low is small
    while (e->high - e->low < 0x1000000ULL) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        e->buf[e->buf_pos++] = byte + 1;  // Output byte+1 so gc()-1 works
        e->low <<= 8;
        e->high = (e->high << 8) | 0xFF;
    }
}

void encode_integer(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (1) {
        int has_bit = (encoded >> temp) & 1;
        if (!has_bit) break;
        encode_bit(e, 1, ctx_base + temp + 1);
        temp++;
        if (temp >= 31) break;
    }

    encode_bit(e, 0, ctx_base + temp + 1);

    for (int i = temp - 1; i >= 0; i--) {
        int bit = (encoded >> i) & 1;
        encode_bit(e, bit, ctx_base);
    }
}

void finish_encoder(Encoder *e) {
    while (e->high - e->low < 0x1000000ULL) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        e->buf[e->buf_pos++] = byte + 1;
        e->low <<= 8;
        e->high = (e->high << 8) | 0xFF;
    }
}

struct Match {
    int offset;
    int length;
};

struct Match find_best_match(unsigned char *data, int data_len, int pos, int max_offset, int max_len) {
    struct Match best = {-1, 0};

    if (pos < 1) return best;

    for (int off = 1; off <= max_offset && off <= pos; off++) {
        int len = 0;
        while (len < max_len && pos + len < data_len &&
               data[pos - off + len] == data[pos + len]) {
            len++;
        }
        if (len > best.length) {
            best.offset = off;
            best.length = len;
        }
    }

    return best;
}

