    fwrite(enc.buf, 1, enc.buf_pos, out);
    fclose(out);

    printf("Compressed: %d bytes (%.1f%%)\n", enc.buf_pos, 100.0 * enc.buf_pos / len);
    free(enc.buf);

    return 0;
}

