    memset(e->bits, 0, sizeof(e->bits));
    memset(e->cc, 0, sizeof(e->cc));
}

void write_bit(SimpleBitEncoder *e, int bit) {
    if (bit) {
        e->bits[e->bit_pos / 8] |= (1 << (7 - (e->bit_pos % 8)));
    }
    e->bit_pos++;
}

void write_integer(SimpleBitEncoder *e, int value, int bits) {
    // Simplified: just write the bits directly
    for (int i = bits - 1; i >= 0; i--) {
        write_bit(e, (value >> i) & 1);
