#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    FILE *out;
    uint64_t low;
    uint64_t high;
    uint32_t cc[1000000];
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->low = 0;
    e->high = 0xFFFFFFFFFFFFFFFFULL;
    memset(e->cc, 0, sizeof(e->cc));
}

void encode_bit(Encoder *e, int bit, int ctx) {
    uint32_t *counts = e->cc + ctx * 2;
    uint64_t range = e->high - e->low + 1;
    uint32_t total = counts[0] + counts[1] + 2;

    uint64_t split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    while ((e->high - e->low) < 0x1000000ULL) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        fputc(byte + 1, e->out);
        e->low <<= 8;
        e->high = ((e->high << 8) | 0xFF);
    }
}

void finish_encoder(Encoder *e) {
    unsigned char byte = (e->low >> 56) & 0xFF;
    fputc(byte + 1, e->out);
}

struct Match {
    int offset;
    int length;
};

struct Match find_best_match(unsigned char *data, int data_len, int pos) {
    struct Match best = {0, 0};

    if (pos < 1) return best;

    for (int off = 1; off <= 31 && off <= pos; off++) {
        int len = 0;
        while (len < 4 && pos + len < data_len &&
               data[pos - off + len] == data[pos + len]) {
            len++;
        }
        if (len > best.length) {
            best.offset = off;
            best.length = len;
        }
    }

    return best;
}

void encode_integer(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (encoded >= (1 << (temp + 1))) {
        encode_bit(e, 1, ctx_base + temp + 1);
        temp++;
    }
    encode_bit(e, 0, ctx_base + temp + 1);

    for (int i = temp - 1; i >= 0; i--) {
        int bit = (encoded >> i) & 1;
        encode_bit(e, bit, ctx_base);
    }
}

int main() {
    unsigned char data[10000];
    FILE *f = fopen("/app/data.txt", "rb");
    int len = fread(data, 1, sizeof(data), f);
    fclose(f);

    // Count commands
    int cmd_count = 0;
    int pos = 0;
    while (pos < len) {
        struct Match m = find_best_match(data, len, pos);
        if (m.length > 0) {
            cmd_count++;
            pos += m.length;
        } else {
            cmd_count++;
            pos++;
        }
    }

    FILE *out = fopen("/app/data.comp", "wb");
    Encoder e;
    init_encoder(&e, out);

    encode_integer(&e, cmd_count, 9, 0);

    pos = 0;
    while (pos < len) {
        struct Match m = find_best_match(data, len, pos);
        if (m.length > 0) {
            encode_bit(&e, 1, 1);
            encode_integer(&e, m.offset - 1, 5, 2);
            encode_integer(&e, m.length - 1, 2, 3);
            pos += m.length;
        } else {
            encode_bit(&e, 0, 1);
            int byte_val = data[pos];
            int sign = (byte_val > 127) ? 1 : 0;
            encode_bit(&e, sign, 8);
            int value = sign ? (256 - byte_val) : byte_val;
            encode_integer(&e, value, 4, 9);
            pos++;
        }
    }

    finish_encoder(&e);
    fclose(out);

    f = fopen("/app/data.comp", "rb");
    fseek(f, 0, SEEK_END);
    long comp_size = ftell(f);
    fclose(f);

    printf("Data: %d, Commands: %d, Compressed: %ld (%.1f%%)\n",
           len, cmd_count, comp_size, 100.0 * comp_size / len);

    return 0;
}

