#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    FILE *out;
    unsigned long long low;
    unsigned long long high;
    unsigned int cc[1000000];
    int bit_count;
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->low = 0;
    e->high = 0xFFFFFFFFFFFFFFFFULL;
    memset(e->cc, 0, sizeof(e->cc));
    e->bit_count = 0;
}

void encode_bit(Encoder *e, int bit, int ctx) {
    unsigned int *counts = e->cc + ctx * 2;
    unsigned long long range = e->high - e->low + 1;
    unsigned int total = counts[0] + counts[1] + 2;

    unsigned long long split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;
    e->bit_count++;

    while ((e->high - e->low + 1) < (1ULL << 32)) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        fputc(byte + 1, e->out);
        e->low <<= 8;
        e->high = ((e->high << 8) | 0xFF);
    }
}

void finish_encoder(Encoder *e) {
    unsigned char byte = (e->low >> 56) & 0xFF;
    fputc(byte + 1, e->out);
}

int main() {
    FILE *out = fopen("/app/test_minimal.comp", "wb");
    Encoder e;
    init_encoder(&e, out);

    printf("Creating minimal test file with 1 command (literal 'X'=88)\n");

    // Encode count = 1
    // value = 1 + 512 = 513
    // 513 = 0b1000000001 (10 bits)
    // Unary: 0 (no 1s), then 9 bits of value

    // Unary: 0 at context 901
    encode_bit(&e, 0, 901);
    printf("Encoded unary 0\n");

    // Value bits (9 bits): 0,0,0,0,0,0,0,0,1
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 0, 891);
    encode_bit(&e, 1, 891);
    printf("Encoded value 1 (9 bits)\n");

    // Now encode 1 literal command
    // Literal flag (0) at context 1
    encode_bit(&e, 0, 1);

    // Sign bit (0 for positive) at context 8
    encode_bit(&e, 0, 8);

    // Value (88) at context 9
    // encode_integer(88, 4, 9)
    // 88 + 16 = 104 = 0b1101000 (7 bits)
    // Unary: 1, 1, 0 (at positions 5, 6, 7)
    // Then 6 bits of value

    encode_bit(&e, 1, 896 + 5);  // Unary
    encode_bit(&e, 1, 896 + 6);  // Unary
    encode_bit(&e, 0, 896 + 7);  // Unary ends
    printf("Encoded unary for value 88\n");

    // 6 value bits of 104 = 0b1101000
    encode_bit(&e, 1, 891);  // Bit 5
    encode_bit(&e, 1, 891);  // Bit 4
    encode_bit(&e, 0, 891);  // Bit 3
    encode_bit(&e, 1, 891);  // Bit 2
    encode_bit(&e, 0, 891);  // Bit 1
    encode_bit(&e, 0, 891);  // Bit 0
    printf("Encoded value 88 (6 bits)\n");

    finish_encoder(&e);
    fclose(out);

    printf("Total bits: %d\n", e.bit_count);

    // Try to decompress
    printf("\nDecompressing...\n");
    system("cat /app/test_minimal.comp | ./decomp");

    return 0;
}

