#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    FILE *out;
    unsigned char buf[100000];
    int buf_pos;
    unsigned long low;
    unsigned long high;
    unsigned long pending_bits;
    unsigned int cc[10000];
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->buf_pos = 0;
    e->low = 0;
    e->high = 0xFFFFFF;
    e->pending_bits = 0;
    memset(e->cc, 0, sizeof(e->cc));
}

void put_bit_direct(Encoder *e, int bit) {
    if (e->buf_pos < 100000 * 8) {
        int byte_idx = e->buf_pos / 8;
        int bit_idx = 7 - (e->buf_pos % 8);
        if (bit) {
            e->buf[byte_idx] |= (1 << bit_idx);
        }
        e->buf_pos++;
    }
}

void encode_bit_simple(Encoder *e, int bit, int ctx) {
    unsigned int *counts = e->cc + ctx * 2;
    unsigned long range = e->high - e->low + 1;

    int total = counts[0] + counts[1] + 2;
    unsigned long split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    while (e->high - e->low < 0x10000) {
        unsigned char byte = (e->low >> 16) & 0xFF;
        e->buf[e->buf_pos++] = byte + 1;
        e->low = ((e->low << 8) & 0xFFFFFF);
        e->high = ((e->high << 8) | 0xFF) & 0xFFFFFF;
    }
}

void encode_integer_simple(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (encoded >= (1 << (temp + 1))) {
        encode_bit_simple(e, 1, ctx_base + temp + 1);
        temp++;
        if (temp > 30) break;
    }
    encode_bit_simple(e, 0, ctx_base + temp + 1);

    for (int i = temp - 1; i >= 0; i--) {
        encode_bit_simple(e, (encoded >> i) & 1, ctx_base);
    }
}

void finish_encoder(Encoder *e) {
    unsigned char byte = (e->low >> 16) & 0xFF;
    e->buf[e->buf_pos++] = byte + 1;
    fwrite(e->buf, 1, e->buf_pos, e->out);
}

int main() {
    unsigned char data[10000];
    FILE *f = fopen("/app/data.txt", "rb");
    int len = fread(data, 1, sizeof(data), f);
    fclose(f);

