    Encoder e;
    init_encoder(&e, out);

    encode_integer_simple(&e, len, 9, 0);

    for (int i = 0; i < len; i++) {
        encode_bit_simple(&e, 0, 1);  // Literal

        int byte_val = data[i];
        int sign = (byte_val > 127) ? 1 : 0;
        encode_bit_simple(&e, sign, 8);

        int value = sign ? (256 - byte_val) : byte_val;
        encode_integer_simple(&e, value, 4, 9);
    }

    finish_encoder(&e);
    fclose(out);

    f = fopen("/app/data.comp", "rb");
    fseek(f, 0, SEEK_END);
    long comp_size = ftell(f);
    fclose(f);

    printf("Compressed: %ld bytes\n", comp_size);

    return 0;
}

