#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    FILE *out;
    long low;
    long high;
    int cc[1000000];
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->low = 0;
    e->high = 0x7FFFFFFF;  // Max value for 32-bit signed long
    memset(e->cc, 0, sizeof(e->cc));
}

void encode_bit(Encoder *e, int bit, int ctx) {
    int *counts = e->cc + ctx * 2;
    long range = e->high - e->low + 1;
    int total = counts[0] + counts[1] + 2;
    long split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    // Normalize range
    while ((e->high ^ e->low) < (1L << 24)) {
        fputc((e->low >> 24) & 0xFF, e->out);
        e->low <<= 8;
        e->high = ((e->high << 8) | 0xFF);
    }
}

void finish_encoder(Encoder *e) {
    fputc((e->low >> 24) & 0xFF, e->out);
    fputc((e->low >> 16) & 0xFF, e->out);
}

void encode_integer(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (encoded >= (1 << (temp + 1))) {
        encode_bit(e, 1, ctx_base + temp + 1);
        temp++;
    }
    encode_bit(e, 0, ctx_base + temp + 1);

    for (int i = temp - 1; i >= 0; i--) {
        encode_bit(e, (encoded >> i) & 1, ctx_base);
    }
}

int main() {
    unsigned char data[10000];
    FILE *f = fopen("/app/data.txt", "rb");
    int len = fread(data, 1, sizeof(data), f);
    fclose(f);

    FILE *out = fopen("/app/data.comp", "wb");
    Encoder e;
    init_encoder(&e, out);

    // Encode as all literals
    encode_integer(&e, len, 9, 0);

    for (int i = 0; i < len; i++) {
        encode_bit(&e, 0, 1);

        int byte_val = data[i];
        int sign = (byte_val > 127) ? 1 : 0;
        encode_bit(&e, sign, 8);

        int value = sign ? (256 - byte_val) : byte_val;
        encode_integer(&e, value, 4, 9);
    }

    finish_encoder(&e);
    fclose(out);

    f = fopen("/app/data.comp", "rb");
    fseek(f, 0, SEEK_END);
    long comp_size = ftell(f);
    fclose(f);

    printf("Compressed: %ld bytes\n", comp_size);
    if (comp_size <= 2500) {
        printf("✓ Within limit!\n");
    }

    return 0;
}

