#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    FILE *out;
    uint64_t low;
    uint64_t high;
    uint32_t cc[1000000];
    uint64_t pending_bits;
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->low = 0;
    e->high = 0xFFFFFFFFFFFFFFFFULL;
    e->pending_bits = 0;
    memset(e->cc, 0, sizeof(e->cc));
}

void encode_bit_with_carry(Encoder *e, int bit) {
    if (bit) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        fputc(byte + 1, e->out);
    }
    while (e->pending_bits--) {
        fputc(bit ? 1 : 256, e->out);
    }
    e->pending_bits = 0;
}

void encode_bit(Encoder *e, int bit, int ctx) {
    uint32_t *counts = e->cc + ctx * 2;
    uint64_t range = e->high - e->low + 1;
    uint32_t total = counts[0] + counts[1] + 2;
    uint64_t split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    while ((e->high ^ e->low) >> 56 == 0) {
        unsigned char byte = (e->low >> 56) & 0xFF;
        fputc(byte + 1, e->out);
        e->low <<= 8;
        e->high = ((e->high << 8) | 0xFF);
    }
}

void finish_encoder(Encoder *e) {
    unsigned char byte = (e->low >> 56) & 0xFF;
    fputc(byte + 1, e->out);
}

void encode_integer(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (encoded >= (1 << (temp + 1))) {
        encode_bit(e, 1, ctx_base + temp + 1);
        temp++;
        if (temp >= 30) break;
    }
    encode_bit(e, 0, ctx_base + temp + 1);

    for (int i = temp - 1; i >= 0; i--) {
        int b = (encoded >> i) & 1;
        encode_bit(e, b, ctx_base);
    }
}

int main() {
    unsigned char data[10000];
    FILE *f = fopen("/app/data.txt", "rb");
    int len = fread(data, 1, sizeof(data), f);
    fclose(f);

    FILE *out = fopen("/app/data.comp", "wb");
    Encoder e;
    init_encoder(&e, out);

    // Encode count
    printf("Encoding count: %d\n", len);
    encode_integer(&e, len, 9, 0);

    // Encode all commands as literals
    for (int i = 0; i < len; i++) {
        unsigned char byte_val = data[i];

        // Literal flag
        encode_bit(&e, 0, 1);

        // Sign bit
        int sign = (byte_val > 127) ? 1 : 0;
        encode_bit(&e, sign, 8);

        // Value
        int value = sign ? (256 - byte_val) : byte_val;
        encode_integer(&e, value, 4, 9);

        if ((i + 1) % 1000 == 0) {
            printf("Encoded %d bytes...\n", i + 1);
        }
    }

    printf("Finishing...\n");
    finish_encoder(&e);
    fclose(out);

    f = fopen("/app/data.comp", "rb");
    fseek(f, 0, SEEK_END);
    long comp_size = ftell(f);
    fclose(f);

    printf("Compressed: %ld bytes (%.1f%%)\n", comp_size, 100.0 * comp_size / len);

    if (comp_size <= 2500) {
        printf("✓ Meets size requirement!\n");
    } else {
        printf("✗ Too large (%ld > 2500)\n", comp_size);
    }

    return 0;
}

