#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    FILE *out;
    long low;
    long high;
    int cc[1000000];
} Encoder;

void init_encoder(Encoder *e, FILE *out) {
    e->out = out;
    e->low = 0;
    e->high = 0x7FFFFFFF;
    memset(e->cc, 0, sizeof(e->cc));
}

void encode_bit(Encoder *e, int bit, int ctx) {
    int *counts = e->cc + ctx * 2;
    long range = e->high - e->low + 1;
    int total = counts[0] + counts[1] + 2;
    long split = e->low + (range * (counts[0] + 1)) / total;

    if (bit) {
        e->low = split + 1;
    } else {
        e->high = split;
    }

    counts[bit]++;

    while ((e->high ^ e->low) < (1L << 24)) {
        fputc(((e->low >> 24) & 0xFF), e->out);
        e->low <<= 8;
        e->high = ((e->high << 8) | 0xFF);
    }
}

void finish_encoder(Encoder *e) {
    fputc(((e->low >> 24) & 0xFF), e->out);
    fputc(((e->low >> 16) & 0xFF), e->out);
}

void encode_integer(Encoder *e, int value, int bits, int ctx) {
    int subtract_it = 1 << bits;
    int encoded = value + subtract_it;
    int ctx_base = ctx * 99;

    int temp = bits;
    while (encoded >= (1 << (temp + 1))) {
        encode_bit(e, 1, ctx_base + temp + 1);
        temp++;
    }
    encode_bit(e, 0, ctx_base + temp + 1);

    for (int i = temp - 1; i >= 0; i--) {
        encode_bit(e, (encoded >> i) & 1, ctx_base);
    }
}

int find_match(unsigned char *data, int len, int pos) {
    // Returns length of best match, or 0 if no good match
    if (pos < 1) return 0;

    int best_len = 0;
    for (int off = 1; off <= 31 && off <= pos; off++) {
        int len_here = 0;
        while (len_here < 4 && pos + len_here < len &&
               data[pos - off + len_here] == data[pos + len_here]) {
            len_here++;
        }
        if (len_here > best_len) {
            best_len = len_here;
        }
    }
    return best_len;
}

int main() {
    unsigned char data[10000];
    FILE *f = fopen("/app/data.txt", "rb");
    int len = fread(data, 1, sizeof(data), f);
    fclose(f);

    FILE *out = fopen("/app/data.comp", "wb");
    Encoder e;
    init_encoder(&e, out);

    int cmd_count = 0;
    int pos = 0;

    // Count commands
    while (pos < len) {
        int match_len = find_match(data, len, pos);
        if (match_len > 0) {
            pos += match_len;
        } else {
            pos++;
        }
        cmd_count++;
    }

    printf("Original: %d bytes, Commands: %d, ", len, cmd_count);

    encode_integer(&e, cmd_count, 9, 0);

    pos = 0;
    while (pos < len) {
        int match_len = find_match(data, len, pos);

        if (match_len > 0) {
            encode_bit(&e, 1, 1);

            // Find offset
            int offset = 0;
            for (int off = 1; off <= 31 && off <= pos; off++) {
                int len_here = 0;
                while (len_here < 4 && pos + len_here < len &&
                       data[pos - off + len_here] == data[pos + len_here]) {
                    len_here++;
                }
                if (len_here == match_len) {
                    offset = off - 1;
                    break;
                }
            }

            encode_integer(&e, offset, 5, 2);
            encode_integer(&e, match_len - 1, 2, 3);
            pos += match_len;
        } else {
            encode_bit(&e, 0, 1);

            unsigned char byte_val = data[pos];
            int sign = (byte_val > 127) ? 1 : 0;
            encode_bit(&e, sign, 8);

            int value = sign ? (256 - byte_val) : byte_val;
            encode_integer(&e, value, 4, 9);
            pos++;
        }
    }

    finish_encoder(&e);
    fclose(out);

    f = fopen("/app/data.comp", "rb");
    fseek(f, 0, SEEK_END);
    long comp_size = ftell(f);
    fclose(f);

    printf("Compressed: %ld bytes (%.1f%%)\n", comp_size, 100.0 * comp_size / len);

    if (comp_size <= 2500) {
        printf("✓ Within limit!\n");
        return 0;
    } else {
        printf("✗ Exceeds limit\n");
        return 1;
    }
}

